const money=(n,c='ARS')=>n==null?'Dato pendiente':new Intl.NumberFormat('es-AR',{style:'currency',currency:c,minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100);
const num=n=>new Intl.NumberFormat('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2}).format((n||0)/100);
const date=d=>d?new Date(d+'T12:00:00').toLocaleDateString('es-AR',{day:'2-digit',month:'short',year:'numeric'}):'Sin fecha informada';
