const shift=(m,n)=>{let d=new Date(m+'-15T12:00:00');d.setMonth(d.getMonth()+n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')};
const sum=a=>a.reduce((t,v)=>t+v,0),uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
const amount=M.amount;
const raw=n=>n==null?'':(n/100).toFixed(2),latest=id=>M.latest(state,id),card=id=>state.cards.find(c=>c.id===id),cname=id=>{const c=card(id);return c?c.bank+' '+c.brand:'Sin tarjeta'},sname=s=>cname(s.card)+' · '+month(s.period),paid=(s,c='ARS')=>M.paid(state,s,c),adjustments=(s,c='ARS')=>sum(state.movements.filter(m=>m.statement===s.id&&m.postClose&&m.currency===c).map(m=>m.amount)),balance=(s,c='ARS')=>M.balance(state,s,c),totalDebt=()=>M.totalDebt(state),usdDebt=()=>M.totalDebt(state,'USD');
const tag=(t,c='')=>`<span class="pill ${c}">${esc(t)}</span>`,button=(text,action,extra='',cls='',ico='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const bankLabel=id=>{let c=card(id);return `<span class="bankmark" style="color:${c.color}">${c.bank==='Mercado Pago'?'MP':c.bank==='Banco Provincia'?'BP':c.bank==='Santander'?'S':'G'}</span><span class="bankname">${esc(c.bank)}<small>${esc(c.brand)}</small></span>`};
const empty=(title,desc,action='')=>`<div class="empty">${icon('layers')}<h2>${title}</h2><p>${desc}</p>${action}</div>`;
