function toast(t){clearTimeout(toastTimer);document.getElementById('toast').textContent=t;toastTimer=setTimeout(()=>document.getElementById('toast').textContent='',6500)}
function options(items,selected){return items.map(([v,t])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`).join('')}
